@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import '../../../support/golden_matrix.dart';
// Goldens are generated by CI (`--update-goldens`); PNGs are not committed.
import 'net_worth_breakdown_test.dart' as base;

void main() {
  for (final v in [...goldenVariants, ...goldenVariantsScaled]) {
    testWidgets('net worth breakdown golden ${v.name}', (tester) async {
      await base.pumpForGolden(tester, v);
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/net_worth_breakdown_${v.name}.png'),
      );
    });
  }
}
